members.type:
: Array<{
    name: string;
    qualified_name: string;
    signature: string | null;
    /**
     * ★ schema v13：**结构化形参表**（`nodes.params` 的 JSON 文本已解析）。
     * ★ 三态，**不要合并**：
     *   · `null` = 该行**没写**这一列（历史行 / 非函数符号）—— **不是**“没有形参”；
     *   · `[]`   = 真的**没有形参**（`()`）—— 这一条不该被当成“没抽到”去修；
     *   · 非空  = 形参表（`name` / `type?` / `optional` / `variadic`，见 `symbol_params.ts`）。
     * 消费方（`derive_mind_map.ts#projectSignature`）据此把“拆字符串”降为兜底。
     */
    params: ParsedParam[] | null;
    /** ★ 行区间（1-based）：原来 DSL 镜像的 `notes` 里带"L12-34"这类注记，读者需要它来复原 */
    start_line: number;
    end_line: number;
  }>

symbols.signature:
mergedApis(root: string | undefined,
  fileRel: string | undefined,
  /** ★ 入参放宽到 `ExpectedApi` 形态（`name` 可选、`signature` 可能缺）—— 免得每个调用点都强转 */
  expected: ReadonlyArray<{ name?: string; signature?: string }> | undefined,
  feature?: string,
  /** ★ 产物与 DSL 的 `ExpectedApi` **可赋值**（`signature` 必填）—— 这样它能直接喂 `diffApis(ExpectedApi[], ExpectedApi[])` */): Array<{ name?: string; signature: string }>
